import requests

def get_price_from_api(stock_name):
    url = f"https://api.example.com/stock/{stock_name}"
    response = requests.get(url)
    if response.status_code == 200:
        data = response.json()
        return data.get("price")
    else:
        raise Exception("API request failed")

def get_current_price(stock_name):
    return get_price_from_api(stock_name)

def get_stock_price(stock_name):
    return get_current_price(stock_name)

def buy_function(stock_name):
    price = get_stock_price(stock_name)
    return price

def buy_stock(stock_name, quantity):
    # Simulate inserting into database
    print(f"Inserting {quantity} shares of {stock_name} into database.")
    price = buy_function(stock_name)
    return price

